[Expected Approach] Using Binary Search - O(log n) Time and O(1) SpaceSince the array is sorted, Binary Search can be used to find k without checking every element.Start with left at the beginning and right at the end of the array. At each step, find the middle index and compare arr[mid] with k.If arr[mid] == k, return mid.If arr[mid] > k, move right to mid - 1 and search the left half.If arr[mid] < k, move left to mid + 1 and search the right half.If k is not found, left points to the position where k should be inserted to keep the array sorted.
            C++

    #include <iostream>
#include <vector>
using namespace std;

int searchInsertK(vector<int> arr, int k) {  
    int left = 0, right = arr.size() - 1;  
    while(left <= right) {  
        int mid = left + (right - left) / 2;  

        // if k is found at mid
        if(arr[mid] == k) {  
            return mid;  
        }  
        // if k is smaller, search in left half
        else if(arr[mid] > k) {  
            right = mid - 1;  
        }  
        // if k is larger, search in right half
        else {  
            left = mid + 1;  
        }  
    }  

    // if k is not found, return insert position
    return left;  
}  

int main() {  

    vector<int> arr = {1, 3, 5, 6};  
    int k = 5;  
    cout << searchInsertK(arr, k) << endl;  

    return 0;  
}  


